// ============================================================================
// ADMIN & SUPER ADMIN PORTAL SCREEN (+ TOP-RIGHT STUDENT WINDOW TAB)
// ============================================================================
class AdminHubPortalScreen extends StatefulWidget {
  const AdminHubPortalScreen({super.key});

  @override
  State<AdminHubPortalScreen> createState() => _AdminHubPortalScreenState();
}

class _AdminHubPortalScreenState extends State<AdminHubPortalScreen> {
  InAppWebViewController? _webCtrl;
  PullToRefreshController? _pullToRefreshCtrl;
  String _activeMode = 'staff'; // 'staff' (default Admin Hub) or 'student' (Student Window)
  bool _isLoading = true;
  DateTime? _lastBackPressTime;

  late final String _decodedAdminHtml;
  late final String _decodedStudentWindowHtml;

  @override
  void initState() {
    super.initState();
    _decodedAdminHtml = utf8.decode(base64Decode(kAdminPortalBase64));
    _decodedStudentWindowHtml = utf8.decode(base64Decode(kStudentWindowBase64));

    _pullToRefreshCtrl = PullToRefreshController(
      settings: PullToRefreshSettings(
        color: const Color(0xFFF5B82E),
        backgroundColor: const Color(0xFF0F172A),
      ),
      onRefresh: () async {
        await _reloadCurrentPortal();
      },
    );
  }

  Future<void> _reloadCurrentPortal() async {
    if (_webCtrl == null) return;
    setState(() => _isLoading = true);
    final String htmlData =
        _activeMode == 'staff' ? _decodedAdminHtml : _decodedStudentWindowHtml;
    await _webCtrl!.loadData(
      data: htmlData,
      mimeType: 'text/html',
      encoding: 'utf-8',
      baseUrl: WebUri('https://script.google.com/'),
    );
  }

  Future<void> _switchMode(String targetMode) async {
    if (_activeMode == targetMode) return;
    setState(() {
      _activeMode = targetMode;
      _isLoading = true;
    });
    await _reloadCurrentPortal();
  }

  Future<void> _handleAndroidBack() async {
    if (_webCtrl != null) {
      try {
        final Object? res = await _webCtrl!.evaluateJavascript(
          source:
              "typeof window.handleAndroidBackButton === 'function' ? window.handleAndroidBackButton() : 'AT_ROOT'",
        );
        final String status = (res ?? 'AT_ROOT').toString();
        if (status == 'HANDLED') {
          return; // Stepped back one view inside current portal
        }
      } catch (_) {}
    }

    // If inside the Student Window tab, pressing Back returns to Admin Hub Home first
    if (_activeMode == 'student') {
      await _switchMode('staff');
      return;
    }

    // At Admin Hub root Home screen: require double-press within 2 seconds to exit
    final DateTime now = DateTime.now();
    if (_lastBackPressTime == null ||
        now.difference(_lastBackPressTime!) > const Duration(seconds: 2)) {
      _lastBackPressTime = now;
      if (!mounted) return;
      ScaffoldMessenger.of(context).clearSnackBars();
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: const Text(
            'Press back again to exit',
            textAlign: TextAlign.center,
            style: TextStyle(
              color: Colors.white,
              fontWeight: FontWeight.w800,
              fontSize: 13,
            ),
          ),
          backgroundColor: const Color(0xFF0F172A),
          behavior: SnackBarBehavior.floating,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(999),
            side: const BorderSide(color: Color(0xFFF5B82E), width: 1.5),
          ),
          margin: const EdgeInsets.symmetric(horizontal: 64, vertical: 20),
          duration: const Duration(seconds: 2),
        ),
      );
      return;
    }

    await SystemNavigator.pop();
  }

  @override
  Widget build(BuildContext context) {
    final String initialHtml =
        _activeMode == 'staff' ? _decodedAdminHtml : _decodedStudentWindowHtml;

    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (bool didPop, Object? _) async {
        if (didPop) return;
        await _handleAndroidBack();
      },
      child: Scaffold(
        backgroundColor: const Color(0xFF0F172A),
        body: SafeArea(
          child: Stack(
            children: <Widget>[
              InAppWebView(
                initialData: InAppWebViewInitialData(
                  data: initialHtml,
                  mimeType: 'text/html',
                  encoding: 'utf-8',
                  baseUrl: WebUri('https://script.google.com/'),
                ),
                initialSettings: InAppWebViewSettings(
                  javaScriptEnabled: true,
                  domStorageEnabled: true,
                  databaseEnabled: true,
                  allowFileAccessFromFileURLs: true,
                  allowUniversalAccessFromFileURLs: true,
                  mediaPlaybackRequiresUserGesture: false,
                  supportZoom: false,
                  useShouldOverrideUrlLoading: true,
                ),
                pullToRefreshController: _pullToRefreshCtrl,
                onWebViewCreated: (InAppWebViewController controller) {
                  _webCtrl = controller;
                  controller.addJavaScriptHandler(
                    handlerName: 'switchAppMode',
                    callback: (List<dynamic> args) {
                      final String target = args.isNotEmpty
                          ? args[0].toString()
                          : (_activeMode == 'staff' ? 'student' : 'staff');
                      _switchMode(target);
                    },
                  );
                },
                onLoadStart: (InAppWebViewController _, WebUri? __) {
                  if (mounted) setState(() => _isLoading = true);
                },
                onLoadStop: (InAppWebViewController _, WebUri? __) async {
                  _pullToRefreshCtrl?.endRefreshing();
                  if (mounted) setState(() => _isLoading = false);
                },
                onReceivedError: (
                  InAppWebViewController _,
                  WebResourceRequest __,
                  WebResourceError ___,
                ) {
                  _pullToRefreshCtrl?.endRefreshing();
                  if (mounted) setState(() => _isLoading = false);
                },
                shouldOverrideUrlLoading: (
                  InAppWebViewController controller,
                  NavigationAction navAction,
                ) async {
                  final WebUri? uri = navAction.request.url;
                  if (uri == null) return NavigationActionPolicy.ALLOW;
                  final String urlStr = uri.toString();
                  if (urlStr.startsWith('https://docs.google.com/') ||
                      urlStr.startsWith('https://drive.google.com/') ||
                      urlStr.startsWith('mailto:') ||
                      urlStr.startsWith('tel:')) {
                    await launchUrl(uri, mode: LaunchMode.externalApplication);
                    return NavigationActionPolicy.CANCEL;
                  }
                  return NavigationActionPolicy.ALLOW;
                },
              ),
              if (_isLoading)
                Positioned(
                  top: 14,
                  left: 0,
                  right: 0,
                  child: Center(
                    child: Container(
                      width: 38,
                      height: 38,
                      padding: const EdgeInsets.all(8),
                      decoration: BoxDecoration(
                        color: const Color(0xFF0F172A),
                        shape: BoxShape.circle,
                        border: Border.all(
                          color: const Color(0xFFF5B82E),
                          width: 1.5,
                        ),
                        boxShadow: <BoxShadow>[
                          BoxShadow(
                            color: Colors.black.withOpacity(0.35),
                            blurRadius: 10,
                          ),
                        ],
                      ),
                      child: const CircularProgressIndicator(
                        strokeWidth: 2.5,
                        valueColor: AlwaysStoppedAnimation<Color>(
                          Color(0xFFF5B82E),
                        ),
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}
